import type { CartLine } from '#shared/types/cart'
import { randomUUID } from 'node:crypto'
import { computeQuote, type Quote } from '#server/utils/quote'

export interface StoredOrder extends Quote {
  id: string
  lines: CartLine[]
}

/** Orders live in server memory only; they are lost when the server restarts. */
const orders = new Map<string, StoredOrder>()

/** Quotes the lines server-side and stores the order with the amounts charged. */
export function createOrder(lines: CartLine[], code?: string): StoredOrder {
  const order: StoredOrder = { id: randomUUID(), lines, ...computeQuote(lines, code) }
  orders.set(order.id, order)
  return order
}

export function getOrder(id: string): StoredOrder | undefined {
  return orders.get(id)
}

import type { CartLine } from '#shared/types/cart'
import { createError, defineEventHandler, readBody } from 'h3'
import { findProduct } from '#server/utils/db'
import { createOrder } from '#server/utils/orders'

export default defineEventHandler(async (event) => {
  const body = await readBody<{ lines?: CartLine[], code?: string }>(event)
  const lines = body?.lines
  if (!Array.isArray(lines) || lines.length === 0)
    throw createError({ statusCode: 400, statusMessage: 'lines must be a non-empty array' })
  for (const line of lines) {
    if (!findProduct(line?.slug))
      throw createError({ statusCode: 400, statusMessage: `Unknown product: ${line?.slug}` })
    if (!Number.isInteger(line.qty) || line.qty < 1)
      throw createError({ statusCode: 400, statusMessage: 'qty must be a positive integer' })
  }
  const { id, subtotal, discount, total } = createOrder(lines, body?.code)
  return { id, subtotal, discount, total }
})

import { createError, defineEventHandler, getRouterParam } from 'h3'
import { findProduct } from '#server/utils/db'
import { getOrder } from '#server/utils/orders'

export default defineEventHandler((event) => {
  const order = getOrder(getRouterParam(event, 'id') ?? '')
  if (!order)
    throw createError({ statusCode: 404, statusMessage: 'Order not found' })
  return {
    id: order.id,
    subtotal: order.subtotal,
    discount: order.discount,
    total: order.total,
    lines: order.lines.map(line => ({ slug: line.slug, name: findProduct(line.slug)?.name ?? line.slug, qty: line.qty })),
  }
})

